from dataclasses import dataclass
@dataclass(frozen=True, slots=True, repr=False)
class A:
    def __repr__(self):
        return "A"
_A: A = A()
@dataclass(frozen=True, slots=True, repr=False)
class B:
    def __repr__(self):
        return "B"
_B: B = B()
T = A | B
def f(t: T, c: bool) -> int:
    if isinstance(t, A):
        return 1
    elif isinstance(t, B):
        return 2
    else:
        if isinstance(t, A):
            if c:
                return 3
        raise RuntimeError("non-exhaustive match")
